-- ============================================================
-- spell_proc
-- ============================================================
-- ProcFlags 0 and Chance 0 inherit PROC_FLAG_KILL and 50/100 from the DBC.
--
-- DisableEffectsMask 1 keeps effect 0 (the rage modifier) out of the proc
-- entirely.  It would be harmless either way -- ADD_FLAT_MODIFIER has no proc
-- handler -- but there is no reason to let a passive modifier participate.
--
-- SpellFamilyName 0: the family filter applies to the triggering event, and a
-- killing blow has no warrior-family spell behind it.
--
-- CanSpellTriggerProcOnEvent short-circuits PROC_FLAG_KILL before the school
-- and hit checks, so HitMask and SpellTypeMask are deliberately 0 here.

DELETE FROM `spell_proc` WHERE `SpellId` = -12285;
INSERT INTO `spell_proc` (`SpellId`, `SchoolMask`, `SpellFamilyName`, `SpellFamilyMask0`, `SpellFamilyMask1`, `SpellFamilyMask2`, `ProcFlags`, `SpellTypeMask`, `SpellPhaseMask`, `HitMask`, `AttributesMask`, `DisableEffectsMask`, `ProcsPerMinute`, `Chance`, `Cooldown`, `Charges`) VALUES
(-12285, 0, 0, 0, 0, 0, 0, 0, 2, 0, 0, 1, 0, 0, 0, 0);

